    ++	ALLOW_ANSI_COLOR_SEQUENCES   = 1<<0,
    ++	ALLOW_DEFAULT_ANSI_SEQUENCES = ALLOW_ANSI_COLOR_SEQUENCES,
    ++	ALLOW_ALL_CONTROL_CHARACTERS = 1<<1,
     +} allow_control_characters = ALLOW_ANSI_COLOR_SEQUENCES;
      
